package media;
network Main {
 submodules: a: media.Endpoint; b: media.Endpoint;
 connections:
  a.tx --> media.Link --> b.rx;
  b.tx --> media.Link --> a.rx;
}

package media;
network Mix {
 submodules: a: media.Endpoint; b: media.Endpoint; c: media.Endpoint; sw: media.Switch;
 connections:
  a.tx --> media.Link --> sw.rx_a;
  sw.tx_a --> media.Link --> a.rx;
  b.tx --> media.Link --> sw.rx_b;
  sw.tx_b --> media.Link --> b.rx;
  c.tx --> media.Link --> sw.rx_c;
  sw.tx_c --> media.Link --> c.rx;
}

package media;
simple Endpoint {
 parameters:
  @class("dir.ethernet.EndpointV2");
  int queueCapacity = default(64);
  double txProcessingDelay @unit(s) = default(0ps);
  double rxProcessingDelay @unit(s) = default(0ps);
 gates: output tx; input rx;
}
simple Switch {
 parameters:
  @class("dir.ethernet.SwitchV2");
  int queueCapacity = default(64);
 gates:
  input rx_a; output tx_a;
  input rx_b; output tx_b;
  input rx_c; output tx_c;
}
channel Link {
 parameters:
  @class("dir.ethernet.LinkV2");
  double bitrate @unit(bps) = default(100Mbps);
  double delay @unit(s) = default(100ns);
}
